function updateSetProgress(){const all=[...$('exerciseInputs').querySelectorAll('[data-set-done]')],done=all.filter(i=>i.checked).length;$('setProgress').textContent=done+' / '+all.length+' Sätze';}
function fillExercises(list){const box=$('exerciseInputs');box.replaceChildren();for(const e of list){const card=A.el('article',undefined,'fit-live-exercise');card.dataset.exerciseName=e.name;const head=A.el('div',undefined,'fit-live-header'),media=A.el('div',undefined,'fit-exercise-media'),copy=A.el('div');copy.append(A.el('h3',e.name),A.el('p',e.weight===null?'Gewicht passend und schmerzfrei wählen':e.weight+' kg als Orientierung','life-muted'));head.append(media,copy);card.append(head);appendExerciseGuide(e,card);const labels=A.el('div',undefined,'fit-set-header');['Satz','kg','Wdh. / Dauer','✓'].forEach(t=>labels.append(A.el('span',t)));card.append(labels);for(let i=0;i<e.sets;i++){const previous=e.setDetails?.[i],row=A.el('div',undefined,'fit-set-row');row.append(A.el('span',String(i+1)));const weight=A.el('input');weight.type='number';weight.min=0;weight.max=1000;weight.step=.5;weight.value=previous?.weight??e.weight??'';weight.dataset.setWeight='';weight.setAttribute('aria-label',e.name+' Satz '+(i+1)+' Gewicht in kg');const reps=A.el('input');reps.value=previous?.reps||e.reps;reps.required=true;reps.maxLength=30;reps.dataset.setReps='';reps.setAttribute('aria-label',e.name+' Satz '+(i+1)+' Wiederholungen oder Dauer');const done=A.el('input');done.type='checkbox';done.dataset.setDone='';done.checked=previous?.done??!!editing;done.setAttribute('aria-label',e.name+' Satz '+(i+1)+' erledigt');done.onchange=()=>{dirty=true;updateSetProgress();};row.append(weight,reps,done);card.append(row);}card.append(button('Alle Sätze dieser Übung bestätigen',()=>{card.querySelectorAll('[data-set-done]').forEach(i=>i.checked=true);dirty=true;updateSetProgress();}));const credit=A.el('p',undefined,'fit-media-credit');card.append(credit);box.append(card);attachMedia(e.name,media,credit);}updateSetProgress();}
function workoutExercises(){return [...$('exerciseInputs').children].map(card=>{const setDetails=[...card.querySelectorAll('.fit-set-row')].map(row=>({weight:row.querySelector('[data-set-weight]').value===''?null:Number(row.querySelector('[data-set-weight]').value),reps:row.querySelector('[data-set-reps]').value.trim(),done:row.querySelector('[data-set-done]').checked}));if(setDetails.some(s=>!s.done))throw new Error('Bitte bestätige die ausgeführten Sätze vor dem Abschließen.');return {name:card.dataset.exerciseName,sets:setDetails.length,reps:setDetails[0].reps,weight:setDetails[0].weight,setDetails};});}
function prepare(r=null){editing=r;$('workoutForm').reset();$('workoutForm').elements.date.value=r?.data.date||A.today();$('workoutForm').elements.notes.value=r?.data.notes||'';const latest=[...workouts].sort((a,b)=>b.data.date.localeCompare(a.data.date)||b.updatedAt.localeCompare(a.updatedAt))[0];fillExercises(r?.data.exercises||TrainingPlan.next(planRecord,workouts,A.today())?.exercises||latest?.data.exercises||defaults.map(([name,reps])=>({name,reps,weight:null,sets:2})));dirty=false;$('workoutEditor').hidden=!r;$('startWorkout').setAttribute('aria-expanded',String(!!r));$('exercisePreviewPanel').hidden=!!r;$('workoutHeading').textContent=r?'Training bearbeiten':(TrainingPlan.next(planRecord,workouts,A.today())?.sessionName||'Deine Einheit');status(r?'Training bearbeiten':'Neues Training vorbereitet',false,'workoutStatus');}
