 const routines=$('routineStrip');routines.replaceChildren();const sessions=planRecord.data.sessions||[{id:'–',name:'Ganzkörper'}];sessions.forEach(session=>{const isNext=session.id===next.sessionId,previousIndex=(sessions.findIndex(x=>x.id===next.sessionId)+sessions.length-1)%sessions.length,isDone=next.done>0&&sessions[previousIndex]?.id===session.id;const tile=A.el('div',undefined,'fit-routine'+(isNext?' next':'')+(isDone?' done':''));tile.append(A.el('strong',isDone?'✓':session.id));const text=A.el('div');text.append(A.el('p',session.name),A.el('small',isNext?'Als Nächstes':isDone?'Zuletzt erledigt':'Danach'));tile.append(text);routines.append(tile);});
 for(const e of next.exercises){const card=A.el('article',undefined,'fit-exercise-card'),media=A.el('div',undefined,'fit-exercise-media'),copy=A.el('div',undefined,'fit-exercise-copy'),credit=A.el('p',undefined,'fit-media-credit');copy.append(A.el('h3',e.name),A.el('p',e.sets+' Sätze · '+e.reps,'fit-exercise-target'),A.el('span',e.weight===null?'Gewicht offen / Körpergewicht':e.weight+' kg zuletzt','fit-exercise-load'));if(e.hint)copy.append(A.el('p',e.hint,'life-muted'));card.append(media,copy);appendExerciseGuide(e,card);card.append(credit);box.append(card);attachMedia(e.name,media,credit);}

