function renderStats(){const sorted=[...measures].sort((a,b)=>a.data.date.localeCompare(b.data.date)||a.updatedAt.localeCompare(b.updatedAt));const latest=sorted.at(-1),stats=$('stats');stats.replaceChildren();for(const [label,val] of [['Zuletzt gemessen',latest?latest.data.weight.toLocaleString('de-DE')+' kg':'Noch kein Messwert'],['Dein Ziel',profile?profile.data.target.toLocaleString('de-DE')+' kg':'Im Profil festlegen']]){const c=A.el('div');c.append(A.el('p',label,'life-muted'),A.el('p',val,'life-stat'));stats.append(c);}const cutoff=A.today();const week=sorted.filter(r=>{const days=(Date.parse(cutoff)-Date.parse(r.data.date))/86400000;return days>=0&&days<7;});if(week.length)stats.append(A.el('p','Mittel der letzten 7 Tage: '+(week.reduce((s,r)=>s+r.data.weight,0)/week.length).toLocaleString('de-DE',{maximumFractionDigits:1})+' kg','life-muted'));
const chart=$('chart');chart.replaceChildren();if(sorted.length<2){chart.append(A.el('p','Ab zwei Messwerten erscheint hier dein Gewichtsverlauf.','life-muted'));return;}const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 600 160');svg.setAttribute('role','img');svg.setAttribute('aria-label','Gewichtsverlauf. Einzelwerte stehen in der Messwerthistorie.');svg.classList.add('life-chart');const w=sorted.map(r=>r.data.weight),min=Math.min(...w)-.5,max=Math.max(...w)+.5,dates=sorted.map(r=>Date.parse(r.data.date)),range=Math.max(1,dates.at(-1)-dates[0]),points=w.map((n,i)=>`${20+(dates[i]-dates[0])/range*560},${140-(n-min)/(max-min)*120}`).join(' '),line=document.createElementNS(ns,'polyline');line.setAttribute('points',points);line.setAttribute('fill','none');line.setAttribute('stroke','currentColor');line.setAttribute('stroke-width','3');svg.append(line);chart.append(svg);}
function renderHistory(){const box=$('history');box.replaceChildren();renderActivities(box);if(!workouts.length&&!activities.length)box.append(A.el('p','Dein erstes gespeichertes Training erscheint hier.','life-muted'));for(const r of [...workouts].sort((a,b)=>b.data.date.localeCompare(a.data.date)||b.updatedAt.localeCompare(a.updatedAt))){const c=A.el('article',undefined,'fit-history-card');c.append(A.el('span','KRAFT · '+(r.data.sessionId||'Studio'),'fit-pill'),A.el('h3',A.date(r.data.date)),A.el('p',r.data.exercises.length+' Übungen · '+r.data.exercises.reduce((n,e)=>n+e.sets,0)+' Sätze','fit-history-metric'));const exerciseDetail=A.el('details');exerciseDetail.append(A.el('summary','Übungen ansehen'));c.append(exerciseDetail);for(const e of r.data.exercises)exerciseDetail.append(A.el('p',`${e.name}: ${e.sets} × ${e.reps}${e.weight===null?'':' · '+e.weight+' kg'}`,'life-muted'));if(r.data.exercises.some(e=>e.setDetails)){const detail=A.el('details');detail.append(A.el('summary','Einzelne Sätze ansehen'));for(const e of r.data.exercises)for(const [i,set] of (e.setDetails||[]).entries())detail.append(A.el('p',e.name+' · Satz '+(i+1)+': '+set.reps+(set.weight===null?'':' · '+set.weight+' kg'),'life-muted'));c.append(detail);}if(r.data.notes)c.append(A.el('p',r.data.notes,'life-muted'));const actions=A.el('div',undefined,'life-actions');actions.append(button('Bearbeiten',()=>{if(busy)return;if(dirty&&!confirm('Ungespeichertes Training verwerfen?'))return;prepare(r);showView('training');$('workoutEditor').hidden=false;$('startWorkout').textContent='Training schließen ×';$('startWorkout').setAttribute('aria-expanded','true');$('exercisePreviewPanel').hidden=true;$('workoutForm').scrollIntoView({behavior:'smooth'});}),button('Löschen',()=>remove('workout',r)));c.append(actions);c.dataset.date=r.data.date;box.append(c);} [...box.children].sort((a,b)=>(b.dataset.date||'').localeCompare(a.dataset.date||'')).forEach(c=>box.append(c));}
function renderMeasures(){const box=$('measurements');box.replaceChildren();if(!measures.length)box.append(A.el('p','Noch keine Messwerte gespeichert.','life-muted'));for(const r of [...measures].sort((a,b)=>b.data.date.localeCompare(a.data.date))){const c=A.el('div');c.append(A.el('p',`${A.date(r.data.date)} · ${r.data.weight.toLocaleString('de-DE')} kg${r.data.waist===null?'':' · Bauchumfang '+r.data.waist+' cm'}`));c.append(button('Löschen',()=>remove('measurement',r)));box.append(c);}}
async function remove(kind,r){if(busy||!confirm('Diesen Datensatz endgültig löschen?'))return;busy=true;try{await A.remove(kind,r);if(kind==='workout'){workouts=workouts.filter(x=>x.id!==r.id);if(editing?.id===r.id)prepare();}else measures=measures.filter(x=>x.id!==r.id);render();status('Datensatz gelöscht.');}catch(e){status(e.message,true);}finally{busy=false;}}
function renderRecipes(){
 const box=$('recipes');box.replaceChildren();const list=filteredRecipes();document.querySelectorAll('[data-meal]').forEach(b=>{const count=b.dataset.meal==='all'?allRecipes().length:allRecipes().filter(r=>r.meal===b.dataset.meal).length;b.textContent=mealNames[b.dataset.meal]+' · '+count;});
 for(const r of list.slice(0,recipeLimit)){
  const portions=portionFor(r.id),c=recipeShell(r);c.dataset.recipeId=r.id;
  const controls=A.el('div',undefined,'life-recipe-controls'),portionLabel=A.el('label','Portionen'),input=A.el('input');input.type='number';input.min=1;input.max=12;input.step=1;input.value=portions;input.setAttribute('aria-label','Portionen für '+r.name);input.dataset.recipePortions=r.id;
  input.onchange=()=>{recipePortions[r.id]=Math.max(1,Math.min(12,Math.round(Number(input.value)||1)));shoppingChecked.clear();renderRecipes();scheduleShopping();};portionLabel.append(input);controls.append(portionLabel);
  const label=A.el('label',undefined,'life-check'),check=A.el('input');check.type='checkbox';check.checked=shoppingSelected.has(r.id);check.onchange=()=>{if(check.checked)shoppingSelected.add(r.id);else shoppingSelected.delete(r.id);shoppingChecked.clear();renderShopping();scheduleShopping();};label.append(check,A.el('span','Für Einkauf'));controls.append(label);c.append(controls);
  const fav=favorites.find(f=>f.data.recipeId===r.id);const favButton=button(fav?'★ Favorit':'☆ Favorit',async()=>{if(busy)return;busy=true;try{if(fav){await A.remove('favorite',fav);favorites=favorites.filter(f=>f.id!==fav.id);}else favorites.push(await A.save('favorite',r.id,{recipeId:r.id}));renderRecipes();}catch(e){status(e.message,true,'shoppingStatus');}finally{busy=false;}});favButton.className='fit-recipe-favorite';favButton.setAttribute('aria-pressed',String(!!fav));favButton.setAttribute('aria-label',r.name+(fav?' aus Favoriten entfernen':' als Favorit speichern'));controls.append(favButton);
  appendRecipeDetails(r,c,portions);const nutritionEditor=c.querySelector('.fit-nutrition-editor');if(nutritionEditor)c.append(nutritionEditor);box.append(c);
 }if(!box.children.length)box.append(A.el('p','Keine Gerichte für diese Auswahl. Ändere Mahlzeit, Filter oder Suchbegriff.','life-muted'));$('recipeCount').textContent=Math.min(recipeLimit,list.length)+' von '+list.length+' passenden Rezepten';$('moreRecipes').hidden=recipeLimit>=list.length;renderShopping();
}
function shoppingItems(){return TrainingPlan.shopping(allRecipes(),[...shoppingSelected],Object.fromEntries(allRecipes().map(r=>[r.id,portionFor(r.id)])));}
function renderShopping(){const box=$('shoppingList');box.replaceChildren();const selected=allRecipes().filter(r=>shoppingSelected.has(r.id)),items=shoppingItems();$('shoppingMeta').textContent=selected.length?selected.length+' Gericht'+(selected.length===1?'':'e')+' · '+selected.map(r=>r.name+': '+portionFor(r.id)+' Portionen').join(' / ')+' · '+shoppingChecked.size+' abgehakt':'Wähle bei deinen Gerichten „Für Einkauf“. Die Mengen passen sich automatisch an die Portionszahl an.';$('copyShopping').disabled=!items.length;
 for(const item of items){const label=A.el('label',undefined,'life-shopping-item'),check=A.el('input');check.type='checkbox';check.checked=shoppingChecked.has(item.key);check.onchange=()=>{if(check.checked)shoppingChecked.add(item.key);else shoppingChecked.delete(item.key);renderShopping();scheduleShopping();};const text=A.el('span',item.amount===null?(item.unscaled?'Originalmenge prüfen: ':'Nach Bedarf: ')+item.name:item.amount.toLocaleString('de-DE',{maximumFractionDigits:2})+' '+item.unit+' '+item.name);if(check.checked)text.classList.add('checked');label.append(check,text);box.append(label);}}
function scheduleShopping(){status('Wird gespeichert …',false,'shoppingStatus');clearTimeout(shoppingTimer);shoppingTimer=setTimeout(()=>{shoppingTimer=null;saveShopping();},450);}
async function saveShopping(){if(!HubAuth.isSignedIn())return;if(shoppingSaving){shoppingQueued=true;return;}const current=epoch;shoppingSaving=true;const data={selected:[...shoppingSelected],checked:[...shoppingChecked],portionsByRecipe:{...recipePortions}};try{const saved=await A.save('shopping','active',data,shoppingRecord?.revision||0);if(current!==epoch)return;shoppingRecord=saved;status('Einkaufsliste gespeichert.',false,'shoppingStatus');}catch(e){if(current===epoch)status(e.message+' Deine aktuelle Liste bleibt sichtbar.',true,'shoppingStatus');}finally{shoppingSaving=false;if(shoppingQueued){shoppingQueued=false;saveShopping();}}}
$('copyShopping').onclick=async()=>{const text='Einkaufsliste\n'+allRecipes().filter(r=>shoppingSelected.has(r.id)).map(r=>r.name+' · '+portionFor(r.id)+' Portionen').join('\n')+'\n\n'+shoppingItems().map(i=>(shoppingChecked.has(i.key)?'[x] ':'[ ] ')+(i.amount===null?(i.unscaled?'Originalmenge prüfen: ':'Nach Bedarf: ')+i.name:i.amount.toLocaleString('de-DE',{maximumFractionDigits:2})+' '+i.unit+' '+i.name)).join('\n');try{await navigator.clipboard.writeText(text);status('Einkaufsliste kopiert.',false,'shoppingStatus');}catch{const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=A.el('a');a.href=url;a.download='einkaufsliste.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Einkaufsliste als Textdatei erstellt.',false,'shoppingStatus');}};
function recipeShell(r){
 const c=A.el('article',undefined,'life-recipe');c.dataset.meal=r.meal||'all';
 const header=A.el('div',undefined,'fit-recipe-heading');if(r.image){const img=A.el('img',undefined,'life-recipe-image');img.src=r.image;img.alt=r.name;img.loading='lazy';img.referrerPolicy='no-referrer';header.append(img);}else{const cover=A.el('div',undefined,'fit-recipe-cover');cover.append(A.el('span',r.veggie?'◉ Vegetarisch':'◉ Alltagsküche'),A.el('strong',r.minutes?'◷ '+r.minutes+' Min.':'Rezeptidee'));header.append(cover);}
 header.append(A.el('h3',r.name));const meta=A.el('div',undefined,'fit-recipe-meta');meta.append(A.el('span',mealNames[r.meal]||'Rezept'));if(r.mealprep)meta.append(A.el('span','Gut vorzubereiten'));if(r.source)meta.append(A.el('span',r.language==='de'?'Wikibooks · Deutsch':'Gespeichertes Rezept'));header.append(meta);c.append(header);attachNutrition(r,c);return c;
}
function appendRecipeDetails(r,card,portions){
 const details=A.el('details',undefined,'fit-recipe-details');details.append(A.el('summary','Zutaten & Zubereitung'));const body=A.el('div',undefined,'fit-recipe-detail-body'),ingredients=A.el('section');ingredients.append(A.el('h4','Zutaten für '+portions+' '+(portions===1?'Portion':'Portionen')));const list=A.el('ul',undefined,'fit-ingredient-list');r.ingredients.forEach(([n,unit])=>{const row=A.el('li');row.append(A.el('strong',(n*portions).toLocaleString('de-DE',{maximumFractionDigits:2})),A.el('span',unit));list.append(row);});(r.unscaled||[]).forEach(t=>list.append(A.el('li',t+' · Originalangabe, bitte prüfen')));ingredients.append(list);if(r.pantry?.length)ingredients.append(A.el('p','Aus dem Vorrat: '+r.pantry.join(', '),'fit-recipe-pantry'));body.append(ingredients);
 const method=A.el('section');method.append(A.el('h4','Zubereitung'));if(Intl.Segmenter){const steps=A.el('ol',undefined,'fit-recipe-steps');for(const part of new Intl.Segmenter('de',{granularity:'sentence'}).segment(r.method)){if(part.segment.trim())steps.append(A.el('li',part.segment.trim()));}method.append(steps);}else method.append(A.el('p',r.method,'fit-recipe-method'));body.append(method);if(r.storage){const storage=A.el('section',undefined,'fit-recipe-storage');storage.append(A.el('h4','Aufbewahren & vorbereiten'),A.el('p',r.storage));body.append(storage);}
 if(r.source){const credits=A.el('div',undefined,'fit-recipe-source'),link=A.el('a','Originalrezept öffnen ↗');link.href=r.source;link.target='_blank';link.rel='noopener noreferrer';credits.append(link);if(r.attribution)credits.append(A.el('p',r.attribution));if(r.imageAttribution){const credit=A.el('a','Bild: '+r.imageAttribution+' · Lizenz');credit.href=r.imageLicense;credit.target='_blank';credit.rel='noopener noreferrer';credits.append(credit);}body.append(credits);}details.append(body);card.append(details);
}

