async function load(){const current=++epoch;resetImport();resetActivity();nutritionRecords=[];accountName='';activities=[];workouts=[];measures=[];profile=null;favorites=[];planRecord=null;shoppingRecord=null;recipePortions={};savedRecipes=[];shoppingSelected.clear();shoppingChecked.clear();clearTimeout(shoppingTimer);render();$('workoutForm').reset();$('profileForm').reset();$('measureForm').reset();prepare();$('measureForm').elements.date.value=A.today();$('activityForm').elements.date.value=A.today();$('importStart').value=planRecord?.data.startDate||A.today();const signed=HubAuth.isSignedIn();$('privateContent').hidden=!signed;if(!signed){status('Bitte melde dich an, um FitPaul zu öffnen.');return;}status('Deine Daten werden geladen …');try{const [w,m,p,f,plans,shopping,custom,extra,nutritionData,identity]=await Promise.all(['workout','measurement','profile','favorite','plan','shopping','recipe','activity','nutrition'].map(A.list).concat(A.request('/auth/me').then(r=>r.json())));if(current!==epoch)return;nutritionRecords=nutritionData;accountName=identity?.user?.name||p.find(r=>r.id==='main')?.data.displayName||'';activities=extra;workouts=w;measures=m;profile=p.find(r=>r.id==='main')||null;favorites=f;savedRecipes=custom.map(r=>r.data);planRecord=plans.find(r=>r.id==='active')||null;shoppingRecord=shopping.find(r=>r.id==='active')||null;if(shoppingRecord){shoppingSelected=new Set(shoppingRecord.data.selected);shoppingChecked=new Set(shoppingRecord.data.checked);recipePortions={...shoppingRecord.data.portionsByRecipe};if(!shoppingRecord.data.portionsByRecipe)for(const r of allRecipes())recipePortions[r.id]=shoppingRecord.data.portions||3;}if(profile)for(const k of ['height','target','sessions','notes','age','formula','pal','displayName','energyTarget'])$('profileForm').elements[k].value=profile.data[k]??({formula:'range',pal:1.4,age:''}[k]??'');$('importStart').value=planRecord?.data.startDate||A.today();prepare();render();status('');}catch(e){if(current===epoch)status(e.message,true);}}
function fillPlanEditor(){const data=planRecord?.data;if(!data)return;const f=$('planForm');for(const k of ['name','startDate','weeks','notes'])f.elements['plan'+k[0].toUpperCase()+k.slice(1)].value=data[k];const days=$('planDays');days.replaceChildren();['So','Mo','Di','Mi','Do','Fr','Sa'].forEach((name,i)=>{const l=A.el('label',undefined,'life-check'),input=A.el('input');input.type='checkbox';input.value=i;input.checked=data.days.includes(i);l.append(input,A.el('span',name));days.append(l);});$('planExercises').replaceChildren();const selector=$('planSession');selector.replaceChildren();const sessions=data.sessions||[{id:'single',name:'Ganzkörper',exercises:data.exercises}];sessions.forEach(s=>{const option=A.el('option',s.id+' · '+s.name);option.value=s.id;selector.append(option);});selector.dataset.active=sessions[0].id;window.fitPlanDraft=structuredClone(data);sessions[0].exercises.forEach(planExerciseRow);}
function planExerciseRow(e){const row=A.el('div',undefined,'life-plan-row');for(const [name,label,type,val] of [['name','Übung','text',e.name],['sets','Sätze','number',e.sets],['reps','Wdh. / Sekunden','text',e.reps],['weight','Startgewicht kg','number',e.weight??'']]){const l=A.el('label',label),i=A.el('input');i.name=name;i.type=type;i.value=val;if(name!=='weight')i.required=true;if(type==='number'){i.min=name==='sets'?1:0;i.max=name==='sets'?6:1000;i.step=name==='sets'?1:.5;}l.append(i);row.append(l);}row.append(button('Entfernen',()=>row.remove()));$('planExercises').append(row);}
$('planForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=$('planForm'),data={name:f.elements.planName.value,startDate:f.elements.planStartDate.value,weeks:Number(f.elements.planWeeks.value),notes:f.elements.planNotes.value,days:[...$('planDays').querySelectorAll('input:checked')].map(i=>Number(i.value)),exercises:[...$('planExercises').children].map(row=>Object.fromEntries([...row.querySelectorAll('input')].map(i=>[i.name,i.name==='sets'?Number(i.value):i.name==='weight'?(i.value===''?null:Number(i.value)):i.value])))};captureSession();if(window.fitPlanDraft?.sessions){data.sessions=window.fitPlanDraft.sessions;data.exercises=data.sessions[0].exercises;}if(window.fitPlanDraft?.strictCycle!==undefined)data.strictCycle=window.fitPlanDraft.strictCycle;if(window.fitPlanDraft?.cycleId)data.cycleId=window.fitPlanDraft.cycleId;if(window.fitPlanDraft?.weekFocus)data.weekFocus=window.fitPlanDraft.weekFocus;if(window.fitPlanDraft?.progressionEnabled!==undefined)data.progressionEnabled=window.fitPlanDraft.progressionEnabled;if(!TrainingPlan.valid(data))return status('Bitte Planname, 2–4 Trainingstage und 1–12 vollständige Übungen prüfen.',true,'planStatus');busy=true;try{planRecord=await A.save('plan','active',data,planRecord?.revision||0);renderPlan();fillPlanEditor();status('Plan gespeichert.',false,'planStatus');}catch(e){status(e.message,true,'planStatus');}finally{busy=false;}};
$('planSession').onchange=()=>{if(!window.fitPlanDraft)return;captureSession();const session=window.fitPlanDraft.sessions?.find(s=>s.id===$('planSession').value);$('planSession').dataset.active=$('planSession').value;$('planExercises').replaceChildren();(session?.exercises||window.fitPlanDraft.exercises).forEach(planExerciseRow);};
function readPlanExercises(){return [...$('planExercises').children].map(row=>Object.fromEntries([...row.querySelectorAll('input')].map(i=>[i.name,i.name==='sets'?Number(i.value):i.name==='weight'?(i.value===''?null:Number(i.value)):i.value])));}
