af.onsubmit=e=>{e.preventDefault();submit('activityForm','activityStatus',async()=>{const optional=n=>af.elements[n].value===''?null:Number(af.elements[n].value);const r=await A.save('activity',activityEditing?.id||crypto.randomUUID(),{date:af.elements.date.value,type:af.elements.type.value,durationMinutes:Number(af.elements.durationMinutes.value),distanceKm:optional('distanceKm'),notes:af.elements.notes.value},activityEditing?.revision||0);activities=activities.filter(x=>x.id!==r.id);activities.push(r);resetActivity();});};
function renderActivities(box){for(const r of [...activities].sort((a,b)=>b.data.date.localeCompare(a.data.date))){const c=A.el('article',undefined,'fit-history-card fit-activity-card');c.append(A.el('span','BEWEGUNG · '+r.data.type,'fit-pill'),A.el('h3',A.date(r.data.date)),A.el('p',r.data.durationMinutes+' min'+(r.data.distanceKm===null?'':' · '+r.data.distanceKm.toLocaleString('de-DE')+' km'),'fit-history-metric'));if(r.data.notes)c.append(A.el('p',r.data.notes,'life-muted'));const actions=A.el('div',undefined,'life-actions');actions.append(button('Bearbeiten',()=>{activityEditing=r;for(const k of ['date','type','durationMinutes','distanceKm','notes'])af.elements[k].value=r.data[k]??'';showView('training');af.closest('details').open=true;af.scrollIntoView({behavior:'smooth'});}),button('Löschen',async()=>{if(busy||!confirm('Diese Aktivität endgültig löschen?'))return;busy=true;try{await A.remove('activity',r);activities=activities.filter(x=>x.id!==r.id);if(activityEditing?.id===r.id)resetActivity();render();}catch(e){status(e.message,true);}finally{busy=false;}}));c.append(actions);c.dataset.date=r.data.date;box.append(c);}}
function renderActivityStats(){const box=$('activityStats');box.replaceChildren();const from=TrainingPlan.addDays(A.today(),-6),week=activities.filter(r=>r.data.date>=from&&r.data.date<=A.today()),strength=workouts.filter(r=>r.data.date>=from&&r.data.date<=A.today());for(const [label,val] of [['Krafttrainings · letzte 7 Tage',strength.length],['Weitere Aktivitäten · letzte 7 Tage',week.length],['Bewegungsdauer · weitere Aktivitäten',week.reduce((n,r)=>n+r.data.durationMinutes,0)+' min'],['Strecke · erfasste Aktivitäten',week.reduce((n,r)=>n+(r.data.distanceKm||0),0).toLocaleString('de-DE')+' km']]){const card=A.el('div',undefined,'fit-progress-card');card.append(A.el('p',label,'life-muted'),A.el('strong',String(val),'life-stat'));box.append(card);}}
function renderWeeks(){const box=$('weekTiles');box.replaceChildren();$('weekPreview').replaceChildren();if(!planRecord)return;const p=planRecord.data,next=TrainingPlan.next(planRecord,workouts,A.today());for(let week=1;week<=p.weeks;week++){const done=Math.max(0,Math.min(p.days.length,(next?.done||0)-(week-1)*p.days.length));const b=button('Woche '+week+' · '+done+'/'+p.days.length+' ✓',()=>{box.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const preview=$('weekPreview');preview.replaceChildren(A.el('h3','Woche '+week+' · Vorschau'),A.el('p',week===1?'Technik und Eingewöhnung':week===2?'Belastbarkeit aufbauen':week===3?'Kraftsteigerung bei sauberer, schmerzfreier Ausführung':'Kraft festigen','life-muted'));for(const session of p.sessions||[{id:'',name:'Ganzkörper',exercises:p.exercises}]){const detail=A.el('details');detail.append(A.el('summary',session.id+' · '+session.name));for(const ex of session.exercises){const main=['Beinpresse','Brustpresse','Latzug','Rudern','Rudermaschine'].includes(ex.name),sets=p.progressionEnabled&&week>=2&&main?3:ex.sets;const card=A.el('article',undefined,'fit-week-exercise'),media=A.el('div',undefined,'fit-exercise-media'),copy=A.el('div'),credit=A.el('p',undefined,'fit-media-credit');copy.append(A.el('h4',ex.name),A.el('p',sets+' × '+ex.reps+(ex.weight===null?'':' · Startorientierung '+ex.weight+' kg')));card.append(media,copy);appendExerciseGuide(ex,card);card.append(credit);detail.append(card);attachMedia(ex.name,media,credit);}preview.append(detail);}preview.append(A.el('p','Die Vorschau verändert dein nächstes Training nicht. Gewichte werden nicht automatisch erhöht.','life-muted'));});b.className='fit-week-tile';b.setAttribute('aria-pressed','false');box.append(b);}}

let importRaw=null,importDraft=null,importEpoch=0;
function resetImport(){importEpoch++;importRaw=null;importDraft=null;$('planFile').value='';$('importPreview').replaceChildren();$('confirmImport').disabled=true;status('',false,'importStatus');}
function previewImport(){importDraft=null;$('confirmImport').disabled=true;$('importPreview').replaceChildren();if(!importRaw)return;try{const isUpdate=$('importMode').value==='update',cycleId=isUpdate?(planRecord?.data.cycleId||'import-'+crypto.randomUUID()):'import-'+crypto.randomUUID();importDraft=TrainingPlan.fromJSON(importRaw,{startDate:$('importStart').value,cycleId});importDraft.strictCycle=isUpdate?(planRecord?.data.strictCycle||false):true;const p=importDraft,box=$('importPreview');box.append(A.el('h3',p.name),A.el('p',p.weeks+' Wochen · '+p.days.map(d=>['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'][d]).join(', ')+' · Start '+A.date(p.startDate),'life-muted'));for(const session of p.sessions||[{id:'',name:'Ganzkörper',exercises:p.exercises}]){const detail=A.el('details');detail.append(A.el('summary',session.id+' · '+session.name));for(const e of session.exercises)detail.append(A.el('p',e.name+' · '+e.sets+' × '+e.reps+(e.weight===null?'':' · '+e.weight+' kg')));box.append(detail);}if(p.notes)box.append(A.el('p',p.notes,'life-muted'));if(isUpdate){const next=TrainingPlan.next({data:p,revision:planRecord?.revision||1},workouts,A.today());box.append(A.el('p','Aktualisierung: deine bisherigen Trainingseinträge bleiben bestehen. Erwartete nächste Einheit: '+(next?.sessionId||next?.sessionName||'noch offen')+'.','life-muted'));}else box.append(A.el('p','Neuer Durchlauf: beginnt mit der ersten Einheit. Alte Trainingseinträge bleiben im Verlauf.','life-muted'));status('Datei geprüft. Bitte Vorschau kontrollieren und anschließend übernehmen.',false,'importStatus');$('confirmImport').disabled=false;}catch(e){status(e.message,true,'importStatus');}}
$('planFile').onchange=async()=>{const file=$('planFile').files[0],current=++importEpoch;importRaw=null;importDraft=null;$('confirmImport').disabled=true;$('importPreview').replaceChildren();if(!file)return;if(file.size>100000)return status('Bitte eine JSON-Datei unter 100 KB wählen.',true,'importStatus');try{const raw=JSON.parse(await file.text());if(current!==importEpoch)return;importRaw=raw;previewImport();}catch(e){if(current===importEpoch)status('Die Datei konnte nicht als JSON gelesen werden. Bitte die Originaldatei aus deinem Trainingschat wählen.',true,'importStatus');}};
$('importStart').onchange=previewImport;$('importMode').onchange=()=>{if($('importMode').value==='new')$('importStart').value=(importRaw?.plan||importRaw)?.startDate||A.today();else $('importStart').value=planRecord?.data.startDate||A.today();previewImport();};
$('confirmImport').onclick=async()=>{if(busy||!importDraft)return;if(dirty&&!confirm('Ungespeichertes Training verwerfen und den geprüften Plan übernehmen?'))return;busy=true;$('confirmImport').disabled=true;const current=epoch;try{const data=structuredClone(importDraft);const imported=await A.save('plan','active',data,planRecord?.revision||0);if(current!==epoch)return;planRecord=imported;resetImport();prepare();render();fillPlanEditor();status('Trainingsplan übernommen. Deine bisherigen Trainings bleiben gespeichert.',false,'importStatus');}catch(e){status(e.message+' Die Vorschau bleibt erhalten.',true,'importStatus');$('confirmImport').disabled=false;}finally{busy=false;}};


const mealNames={all:'Alle',breakfast:'Frühstück',snack:'Snacks',lunch:'Mittagessen',dinner:'Abendessen'};
function filteredRecipes(){const filter=$('recipeFilter').value,fold=t=>String(t).toLocaleLowerCase('de-DE').replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss'),terms=fold($('recipeSearch').value.trim()).split(/\s+/).filter(Boolean);return allRecipes().filter(r=>(recipeMeal==='all'||r.meal===recipeMeal)&&(filter==='all'||filter==='quick'&&r.minutes!==null&&r.minutes<=20||filter==='veggie'&&r.veggie||filter==='mealprep'&&r.mealprep||filter==='favorites'&&favorites.some(f=>f.data.recipeId===r.id))&&terms.every(t=>fold(r.name+' '+r.ingredients.map(i=>i[1]).join(' ')+' '+(r.veggie?'vegetarisch':'')+' '+(mealNames[r.meal]||'')).includes(t)));}
$('recipeSearch').oninput=()=>{recipeLimit=12;renderRecipes();};$('moreRecipes').onclick=()=>{recipeLimit+=12;renderRecipes();};
document.querySelectorAll('[data-meal]').forEach(b=>{const count=b.dataset.meal==='all'?starterRecipes.length:starterRecipes.filter(r=>r.meal===b.dataset.meal).length;b.textContent=mealNames[b.dataset.meal]+' · '+count;b.onclick=()=>{recipeMeal=b.dataset.meal;recipeLimit=12;document.querySelectorAll('[data-meal]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderRecipes();};});

