document.addEventListener('visibilitychange',()=>{if(!document.hidden)renderWelcome();});
$('energySettings').onclick=()=>{showView('settings');$('profileForm').scrollIntoView({behavior:'smooth'});};
function renderEnergy(){const box=$('energyStats');box.replaceChildren();const latest=[...measures].filter(r=>r.data.date<=A.today()).sort((a,b)=>b.data.date.localeCompare(a.data.date)||b.updatedAt.localeCompare(a.updatedAt))[0],calc=FitInsights.energy(profile?.data,latest?.data.weight),target=FitInsights.targets(profile?.data,latest?.data.weight),format=(ns,unit)=>[...new Set(ns.map(n=>Math.round(n)))].map(n=>n.toLocaleString('de-DE')).join('–')+' '+unit;const metrics=[['Ruhebedarf · geschätzt',calc?format(calc.rest.map(n=>Math.round(n/10)*10),'kcal'):'Profil ergänzen'],['Alltagsbedarf · geschätzt',calc?format(calc.maintenance.map(n=>Math.round(n/10)*10),'kcal'):'Alter und Messwert benötigt'],['Kalorienziel · Tagesorientierung',target?format(target.kcal,'kcal'):'Profil ergänzen'],['Eiweiß · Tagesorientierung',target?'ca. '+target.protein+' g':'Profil ergänzen'],['Kohlenhydrate · Tagesorientierung',target?'ca. '+format(target.carbs,'g'):'Profil ergänzen'],['Fett · Tagesorientierung',target?'ca. '+format(target.fat,'g'):'Profil ergänzen']];for(const [i,[label,val]] of metrics.entries()){const card=A.el('div',undefined,'fit-energy-card'),caption=A.el('p',undefined,'life-muted'),icon=A.el('span',['🌙','🚶','🎯','🥚','🌾','🥑'][i],'fit-energy-icon');icon.setAttribute('aria-hidden','true');caption.title=label;caption.append(icon,A.el('span',label.split(' · ')[0]));card.append(caption,A.el('strong',val));box.append(card);}$('energyNote').textContent=(calc?'Berechnet mit '+latest.data.weight.toLocaleString('de-DE')+' kg vom '+A.date(latest.data.date)+', '+profile.data.age+' Jahren und '+profile.data.height+' cm. '+((profile.data.formula||'range')==='range'?'Spanne zwischen den beiden Formeln; Auswahl im Profil. ':''):'Ergänze dein Alter im Profil und speichere einen Gewichtsmesswert. ')+(target?(target.manual?'Dein Kalorienziel ist im Profil selbst festgelegt. ':target.deficit?'Startorientierung zur Abnahme: geschätzter Alltagsbedarf minus rund 300 kcal. ':'Kalorienziel orientiert sich am geschätzten Alltagsbedarf. ')+'Eiweiß ca. 1,6 g/kg, Fett ca. 30 % der Zielenergie, Kohlenhydrate als Rest; auf 5 g gerundet. ':'')+'Individuelle Richtwerte zum Anpassen an Gewichtsverlauf, Hunger und Trainingsleistung. Kein Ernährungsprotokoll: Einkaufen zählt nicht als gegessen. Eine Mahlzeit aus jeder Kategorie deckt deinen Tagesbedarf nicht automatisch vollständig ab.';}


function nutritionRows(recipe){const saved=nutritionRecords.find(r=>r.data.recipeId===recipe.id);if(saved)return structuredClone(saved.data.rows);const defs=recipe.nutrition;if(defs)return defs.map(([foodId,grams],i)=>({foodId,grams,label:recipe.id==='couscous'?['Couscous','Kichererbsen','Gurke','Tomate','Körniger Frischkäse','Olivenöl'][i]:(recipe.ingredients[i]?.[1]||'Zutat')}));return [...recipe.ingredients.map(([n,label])=>({label,grams:/^g /.test(label)?n:null,foodId:''})),...(recipe.unscaled||[]).map(label=>({label,grams:null,foodId:''}))];}
function attachNutrition(recipe,card){const rows=nutritionRows(recipe),result=FitInsights.nutrition(rows,foods),badges=A.el('div',undefined,'fit-macros');for(const [key,label,unit] of [['kcal','kcal',''],['protein','Eiweiß',' g'],['carbs','Kohlenh.',' g'],['fat','Fett',' g']]){const b=A.el('div');b.append(A.el('strong',result.complete?Math.round(result.total[key]).toLocaleString('de-DE')+unit:'—'),A.el('span',label));badges.append(b);}card.append(badges,A.el('p',result.complete?'Schätzung pro Portion · BLS 4.0':'Noch unvollständig · '+result.resolved+'/'+rows.length+' Zutaten zugeordnet','fit-nutrition-note'));const details=A.el('details',undefined,'fit-nutrition-editor');details.append(A.el('summary',result.complete?'Nährwerte prüfen & anpassen':'Nährwerte ergänzen'));details.append(A.el('p','Gramm pro Portion: Lebensmittel und Mengen prüfen, insbesondere roh/gegart und Fettgehalt. Vorratsgewürze und nicht bezifferte Zugaben sind nicht enthalten. Produktspezifische Angaben können abweichen. Diese Angaben ändern nur die Nährwertberechnung; Rezept und Einkaufsliste behalten ihre Originalmengen.','life-muted'));if(recipe.id==='chili')details.append(A.el('p','Annahme: mageres Hack als Rindertatar mit 3 % Fett. Bei anderem Hack bitte ändern.','life-muted'));if(recipe.id==='chicken')details.append(A.el('p','Annahmen: Leipziger-Allerlei-Mischung; 15 ml Sojasauce näherungsweise 15 g.','life-muted'));if(recipe.id==='lentils')details.append(A.el('p','Annahmen: generische trockene Linsen und Joghurt mit 3,5 % Fett.','life-muted'));const editors=[];for(const row of rows){const entry=A.el('div',undefined,'fit-nutrient-row'),title=A.el('strong',row.label),search=A.el('input'),grams=A.el('input'),selected=A.el('p',undefined,'life-muted'),results=A.el('div',undefined,'fit-food-results');let chosen=row.foodId;const food=foods.find(f=>f.id===chosen);selected.textContent=food?food.name:'Noch kein Lebensmittel ausgewählt';search.type='search';search.placeholder='Lebensmittel suchen, z. B. Reis roh';search.setAttribute('aria-label','Lebensmittel für '+row.label);grams.type='number';grams.min=0.1;grams.max=100000;grams.step=.1;grams.value=row.grams??'';grams.setAttribute('aria-label','Gramm pro Portion für '+row.label);const gLabel=A.el('label','Gramm pro Portion');gLabel.append(grams);search.oninput=()=>{results.replaceChildren();const query=search.value.trim().toLocaleLowerCase('de-DE');if(query.length<2)return;const tokens=query.split(/\s+/);const found=foods.filter(f=>tokens.every(t=>f.name.toLocaleLowerCase('de-DE').includes(t))).slice(0,12);for(const f of found)results.append(button(f.name,()=>{chosen=f.id;selected.textContent=f.name;search.value='';results.replaceChildren();}));if(!found.length)results.append(A.el('p','Keine Treffer. Suchbegriff vereinfachen.','life-muted'));};entry.append(title,selected,search,results,gLabel);details.append(entry);editors.push(()=>({label:row.label,foodId:chosen,grams:grams.value===''?null:Number(grams.value)}));}const note=A.el('p',undefined,'life-status');details.append(button('Nährwerte privat speichern',async()=>{if(busy)return;const current=epoch;busy=true;note.textContent='Wird gespeichert …';try{const old=nutritionRecords.find(r=>r.data.recipeId===recipe.id),saved=await A.save('nutrition',recipe.id,{recipeId:recipe.id,rows:editors.map(fn=>fn())},old?.revision||0);if(current!==epoch)return;nutritionRecords=nutritionRecords.filter(r=>r.id!==saved.id);nutritionRecords.push(saved);renderRecipes();status('Nährwertzuordnung gespeichert.',false,'shoppingStatus');}catch(e){note.textContent=e.message;}finally{busy=false;}}),note);if(result.complete)details.append(A.el('p','Für '+portionFor(recipe.id)+' Portionen insgesamt: ca. '+Math.round(result.total.kcal*portionFor(recipe.id)).toLocaleString('de-DE')+' kcal.','life-muted'));const link=A.el('a','Quelle: BLS 4.0 · FoodIndex · CC BY 4.0');link.href='https://food-index.de/developers';link.target='_blank';link.rel='noopener noreferrer';details.append(link);card.append(details);}

fetch('/data/nutrition/bls-4.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{foods=data.foods;renderRecipes();}).catch(()=>{foods=[];renderRecipes();});
window.addEventListener('hub-auth-change',load);window.addEventListener('beforeunload',e=>{if(dirty||shoppingTimer||shoppingSaving){e.preventDefault();e.returnValue='';}});load();
